CREATE TABLE users (
	id SERIAL NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	email VARCHAR(255) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	role VARCHAR(20) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT users_pkey PRIMARY KEY (id)
);
CREATE UNIQUE INDEX ix_users_email ON users (email);
CREATE INDEX ix_users_id ON users (id);

CREATE TABLE submissions (
	id SERIAL NOT NULL, 
	user_id INTEGER NOT NULL, 
	submission_type VARCHAR(20) NOT NULL, 
	detected_language VARCHAR(50), 
	is_news BOOLEAN, 
	news_confidence DOUBLE PRECISION, 
	combined_risk_score DOUBLE PRECISION, 
	final_label VARCHAR(50) NOT NULL, 
	final_label_source VARCHAR(50) NOT NULL, 
	admin_comment TEXT, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT submissions_pkey PRIMARY KEY (id), 
	CONSTRAINT submissions_user_id_fkey FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);
CREATE INDEX ix_submissions_id ON submissions (id);
CREATE INDEX ix_submissions_user_id ON submissions (user_id);

CREATE TABLE text_submissions (
	id SERIAL NOT NULL, 
	submission_id INTEGER NOT NULL, 
	input_text TEXT NOT NULL, 
	detected_language VARCHAR(50), 
	text_prediction VARCHAR(50), 
	text_confidence DOUBLE PRECISION, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT text_submissions_pkey PRIMARY KEY (id), 
	CONSTRAINT text_submissions_submission_id_fkey FOREIGN KEY(submission_id) REFERENCES submissions (id) ON DELETE CASCADE, 
	CONSTRAINT text_submissions_submission_id_key UNIQUE NULLS DISTINCT (submission_id)
);
CREATE INDEX ix_text_submissions_id ON text_submissions (id);

CREATE TABLE image_submissions (
	id SERIAL NOT NULL, 
	submission_id INTEGER NOT NULL, 
	image_path VARCHAR(512) NOT NULL, 
	original_filename VARCHAR(255), 
	mime_type VARCHAR(100), 
	file_size_bytes INTEGER, 
	ocr_text TEXT, 
	ocr_confidence DOUBLE PRECISION, 
	detected_language VARCHAR(50), 
	image_score DOUBLE PRECISION, 
	manipulation_prediction VARCHAR(50), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	text_prediction VARCHAR(50), 
	text_confidence DOUBLE PRECISION, 
	CONSTRAINT image_submissions_pkey PRIMARY KEY (id), 
	CONSTRAINT image_submissions_submission_id_fkey FOREIGN KEY(submission_id) REFERENCES submissions (id) ON DELETE CASCADE, 
	CONSTRAINT image_submissions_submission_id_key UNIQUE NULLS DISTINCT (submission_id)
);
CREATE INDEX ix_image_submissions_id ON image_submissions (id);

CREATE TABLE explainability (
	id SERIAL NOT NULL, 
	submission_id INTEGER NOT NULL, 
	highlighted_words TEXT, 
	heatmap_path VARCHAR(512), 
	explanation_summary TEXT, 
	model_version VARCHAR(50), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT explainability_pkey PRIMARY KEY (id), 
